<?php
declare(strict_types=1);

// ══════════════════════════════════════════════════════════════════
// 誕生花365日記事「素材カード方式」用データ（花の名前をキーにした素材カード）。
//
// 背景：花言葉と花の説明だけの記事は独自性が低いという指摘を受け、記事本文を
// 花言葉に依存せず組み立てるための下準備データとして新設。このファイル自体は
// 記事本文ではなく、記事執筆時に参照する「素材」を格納する。
//
// 各カードの根拠：
// - hook / observations は、DAYINFO_FLOWER_DESCRIPTIONS（flower-descriptions-data.php）
//   に記載された当該花（または同一種のベースエントリ）の説明文に基づく。
//   外部の一般知識・伝聞での断定は行っていない。
// - primaryType / secondaryType は下記10種のtaxonomyから選択する。
//   season / color / scent / shape / name_origin / myth / food_culture /
//   annual_event / gift / lifestyle
// - 開花期が誕生日の月と一致しない花（説明文が「初夏」「夏」等、または「春」とだけ
//   記載され早春・冬からの継続が明記されていない花）は season 型を選定していない。
// - shortageLevel：null＝A（素材十分）／'B'＝素材が少なく後で補強候補／
//   'C'＝要調査・最優先で補強。flower-descriptions-data.php の記述が短く、独自の
//   情景を組み立てにくい花に付与している。
// - emotion はメッセージ文の「方向性」のみを示す短い言葉。本文そのものはここでは
//   書かない（記事生成フェーズで別途執筆する）。
// ══════════════════════════════════════════════════════════════════

